            if (raw.isEmpty()) {
                body.set(new ValidSetting(key, null, request.user(), null, null)); // blank: off
                return;
            }
            try {
                body.set(new ValidSetting(key, null, request.user(), LocalDate.parse(raw), null));
            } catch (DateTimeParseException e) {
                throw new InvalidSettingException("The entry date must be a date (YYYY-MM-DD), or blank for off");
            }
            return;
        }
        if (TERMS.equals(key) || key.startsWith(GRADE_TERMS)) {
            if (!DAYS.matcher(raw).matches()) {
                throw new InvalidSettingException("The terms must be a whole number of days, 0 or more");
            }
            body.set(new ValidSetting(key, new BigDecimal(Integer.parseInt(raw)), request.user(), null, from));
            return;
        }
        if (!GRACE_DAYS.equals(key) && key.startsWith(GRADE_GRACE)) {
            if (raw.isEmpty()) {
                body.set(new ValidSetting(key, null, request.user(), null, from)); // blank: none
                return;
            }
            if (!DAYS.matcher(raw).matches()) {
                throw new InvalidSettingException("A grade's grace days must be a whole number of days, 0 or more, or blank for none");
            }
            body.set(new ValidSetting(key, new BigDecimal(Integer.parseInt(raw)), request.user(), null, from));
            return;
        }
        if (LATE_PCT.equals(key)) {
            if (!PERCENT.matcher(raw).matches()) {
                throw new InvalidSettingException("The late percent must be a percent of 0.00 or more with at most two decimals");
            }
            body.set(new ValidSetting(key, new BigDecimal(raw).setScale(2), request.user(), null, from));
            return;
        }
        if (CAP.equals(key)) {
            if (raw.isEmpty()) {
                body.set(new ValidSetting(key, null, request.user(), null, from)); // blank: no cap
                return;
            }
            if (!AMOUNT.matcher(raw).matches()) {
                throw new InvalidSettingException("The cap must be an amount of 0.00 or more with at most two decimals, or blank for none");
            }
            body.set(new ValidSetting(key, new BigDecimal(raw).setScale(2), request.user(), null, from));
            return;
        }
        if (PROOF_THRESHOLD.equals(key) || key.startsWith(GRADE_PROOF_THRESHOLD)) {
            if (raw.isEmpty()) {
                body.set(new ValidSetting(key, null, request.user(), null, from)); // blank: none
                return;
            }
            if (!AMOUNT.matcher(raw).matches()) {
                throw new InvalidSettingException("The proof threshold must be an amount of 0.00 or more with at most two decimals, or blank for none");
            }
            body.set(new ValidSetting(key, new BigDecimal(raw).setScale(2), request.user(), null, from));
            return;
        }
        if (NOTE_THRESHOLD.equals(key)) {
            if (raw.isEmpty()) {
                body.set(new ValidSetting(key, null, request.user(), null, from)); // blank: none
                return;
            }
            if (!AMOUNT.matcher(raw).matches()) {
                throw new InvalidSettingException("The note threshold must be an amount of 0.00 or more with at most two decimals, or blank for none");
            }
            body.set(new ValidSetting(key, new BigDecimal(raw).setScale(2), request.user(), null, from));
            return;
        }
        if (FLOOR.equals(key)) {
            if (!AMOUNT.matcher(raw).matches()) {
                throw new InvalidSettingException("The floor must be an amount of 0.00 or more with at most two decimals");
            }
            body.set(new ValidSetting(key, new BigDecimal(raw).setScale(2), request.user(), null, from));
            return;
        }
        if (raw.isEmpty()) {
            body.set(new ValidSetting(key, null, request.user(), null, from)); // blank: no limit
            return;
        }
        if (!AMOUNT.matcher(raw).matches()) {
            throw new InvalidSettingException("The clerk limit must be an amount of 0.00 or more with at most two decimals");
        }
        body.set(new ValidSetting(key, new BigDecimal(raw).setScale(2), request.user(), null, from));
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class SaveSetting {
    public void save(@PathVariable("sheetId") String sheetId, @Val ValidSetting setting, @Val RollupFigures before,
            Settings settings, Sheets sheets, Rollup rollup, Audit audit, ObjectResponse<SettingsResponse> response) {
        if (setting.roles() != null) {
            settings.setPermission(sheetId, setting.key().substring(ValidateSetting.PERM.length()), setting.roles());
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + setting.user()
                    + " key=" + setting.key() + " value=" + setting.roles());
            rollup.recordChanges(sheetId, setting.user(), before);
            response.send(settings.load(sheetId));
            return;
        }
        if (ValidateSetting.POLICY_DATE.equals(setting.key())
                || ValidateSetting.PERIOD_NUMBERING_FROM.equals(setting.key())) {
            if (setting.roles() != null) {
            settings.setPermission(sheetId, setting.key().substring(ValidateSetting.PERM.length()), setting.roles());
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + setting.user()
                    + " key=" + setting.key() + " value=" + setting.roles());
            rollup.recordChanges(sheetId, setting.user(), before);
            response.send(settings.load(sheetId));
            return;
        }
        if (ValidateSetting.POLICY_DATE.equals(setting.key())) {
                settings.setPolicyDate(sheetId, setting.date());
            } else {
                settings.setPeriodNumberingFrom(sheetId, setting.date());
            }
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + setting.user()
                    + " key=" + setting.key() + " value=" + (setting.date() == null ? "" : setting.date().toString()));
            rollup.recordChanges(sheetId, setting.user(), before);
            response.send(settings.load(sheetId));
            return;
        }
        if (ValidateSetting.ENTRY_DATE.equals(setting.key())) {
            settings.setEntryDate(sheetId, setting.date());
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + setting.user()
                    + " key=" + setting.key() + " value=" + (setting.date() == null ? "" : setting.date().toString()));
            rollup.recordChanges(sheetId, setting.user(), before);
            response.send(settings.load(sheetId));
            return;
        }
        if (ValidateSetting.GRACE_DAYS.equals(setting.key())) {
            settings.setGraceDays(sheetId, setting.value() == null ? null : setting.value().intValue());
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + setting.user()
                    + " key=" + setting.key() + " value=" + (setting.value() == null ? "" : setting.value().toPlainString()));
            rollup.recordChanges(sheetId, setting.user(), before);
            response.send(settings.load(sheetId));
            return;
        }
        if (ValidateSetting.FISCAL_START_MONTH.equals(setting.key())) {
            settings.setFiscalStartMonth(sheetId, setting.value().intValue());
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + setting.user()
                    + " key=" + setting.key() + " value=" + setting.value().intValue());
            rollup.recordChanges(sheetId, setting.user(), before);
            response.send(settings.load(sheetId));
            return;
        }
        if (ValidateSetting.PARENT.equals(setting.key())) {
            settings.setParent(sheetId, setting.text());
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + setting.user()
                    + " key=" + setting.key() + " value=" + (setting.text() == null ? "" : setting.text()));
            rollup.recordChanges(sheetId, setting.user(), before);
            response.send(settings.load(sheetId));
            return;
        }
        if (ValidateSetting.ALERT_THRESHOLD.equals(setting.key())) {
            settings.setAlertThreshold(sheetId, setting.value());
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + setting.user()
                    + " key=" + setting.key() + " value=" + (setting.value() == null ? "" : setting.value().toPlainString()));
            rollup.recordChanges(sheetId, setting.user(), before);
            response.send(settings.load(sheetId));
            return;
        }
        if (ValidateSetting.POT.equals(setting.key())) {
            settings.setPot(sheetId, setting.value());
            audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + setting.user()
                    + " key=" + setting.key() + " value=" + (setting.value() == null ? "" : setting.value().toPlainString()));
            rollup.recordChanges(sheetId, setting.user(), before);
            response.send(settings.load(sheetId));
            return;
        }
        // Recorded from its from-date (the sheet's today when none was given), keeping the values recorded from other dates.
        settings.setFrom(sheetId, setting.key(), setting.from() != null ? setting.from() : sheets.today(sheetId), setting.value());
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + setting.user()
                + " key=" + setting.key() + " value=" + (setting.value() == null ? "" : setting.value().toPlainString())
                + (setting.from() == null ? "" : " from=" + setting.from()));
        rollup.recordChanges(sheetId, setting.user(), before);
        response.send(settings.load(sheetId));
    }
}
package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A setting that passed validation: its key and its value at two decimals (terms: whole days)
 *  (a clerk limit or cap of null: none); a policy date or period numbering from has its date in date (null: blank) and no value.
 *  A dated setting's from is the date its value is in force from (null: none given, the sheet's today).
 *  A permission (perm-<action>) has its roles, comma separated ("" for the standing rule), and no value.
 *  The parent has the parent sheet id in text (null: none) and no value. */
public record ValidSetting(String key, BigDecimal value, String user, LocalDate date, LocalDate from, String roles, String text) {

    public ValidSetting(String key, BigDecimal value, String user, LocalDate date, LocalDate from, String roles) {
        this(key, value, user, date, from, roles, null);
    }

    public ValidSetting(String key, BigDecimal value, String user, LocalDate date, LocalDate from) {
        this(key, value, user, date, from, null, null);
    }
}
