20	// due-total is at most it; blank: none; saved like the policy date) and the role each user name holds (clerk unless set to steward or viewer — a viewer sees everything and changes nothing).
21	// The clerk limit, the floor, the terms, each grade's terms, the late percent and the cap are dated: each has a from-date
22	// field (blank: the sheet's today) and is saved as its value from that date, keeping the values from other dates; each
23	// shows the value in force on the sheet's today. The proof threshold (two decimals; blank: none; saved like the cap) is dated
24	// too: a claim whose due is above the one in force on its date needs a proof to be settled or approved. So is the note
25	// threshold (two decimals; blank: none; saved like the cap): a claim whose due is above the one in force on its date cannot be opened with an empty note. A claim takes the floor, late percent and terms in force on its date.
26	// The permission matrix (not dated): for each of open, settle, void, reassign, close and reopen, the roles that may take it,
27	// comma separated (blank: the standing rule — open, settle, void and close by clerk and steward, reassign and reopen by steward);
28	// saved like the cap. The grace days (not dated; whole days; blank: off; saved like the cap): when the sheet's today is changed,
29	// every open period whose to-date plus them is before the new today is closed. The entry date (not dated; a date; blank: off;
30	// saved like the cap): while set, it is the default date of a new claim (the claim form, the quick-add bar, a pasted line
31	// with a blank date, a correction) in place of the sheet's today. The pot (not dated; two decimals; blank: none; saved like
32	// the cap): each member of a balanced pool shows their cut of it. The alert threshold (not dated; two decimals; blank: off;
33	// saved like the cap): a person whose due-total crosses above it is audited as an ALERT. The parent (not dated; a sheet id; blank: none; saved like
34	// the cap): a grade with no rate in force on a date on this sheet takes the parent's, then the parent's parent's, up to three
35	// levels up. The sheet itself, a sheet that has this sheet as an ancestor, or a sheet never loaded is refused.
36	// A steward delegates the steward role to a user for a from-date and a to-date, inclusive (blank: the sheet's today): while the
37	// sheet's today is inside them the user acts as a steward in every rule. Anyone but a steward (by the role set), or a to-date
38	// before the from-date, is refused.
39	// Each grade's grace days (dated; whole days; blank: none; saved like the cap): a claim whose person's grade in force on its
40	// date has grace days in force on that date is overdue only once its due-by plus them is before the sheet's today, and its
41	// late charge's 30-day boundaries count from its due-by plus them. Its due-by is shown as it is.
42	// Each grade's proof threshold (dated; two decimals; blank: none; saved like the cap): a claim whose person's grade in force
43	// on its date has one in force on that date takes it in place of the sheet's proof threshold.
44	// The fiscal year start month (not dated; 1 to 12; 1 unless set; saved when its field is filled, together with any other
45	// field filled): a fiscal year is named FY<yyyy> by the calendar year its first day falls in.
46	export function SettingsPanel() {
47	  const [sheet] = useSearchParam('sheet', asString);
48	  const [user] = useSearchParam('user', asString);
49	  const settings = useSettings(sheet);
50	  const queryClient = useQueryClient();
51	  const submitSetting = useSubmitOnce();
52	  const submitRole = useSubmitOnce();
53	  const submitDelegate = useSubmitOnce();
54	  const [limit, setLimit] = useState('');
55	  const [floor, setFloor] = useState('');
56	  const [terms, setTerms] = useState('');
57	  // Each grade's own terms, by grade, as typed.
58	  const [gradeTerms, setGradeTerms] = useState<Record<string, string>>({});
59	  const [latePct, setLatePct] = useState('');
60	  const [fiscalStart, setFiscalStart] = useState('');
61	  // Each grade's grace days, by grade, as typed; each may be saved blank (none), so entering its field marks it as one to save.
62	  const [gradeGrace, setGradeGrace] = useState<Record<string, string>>({});
63	  const graceGradeChosen = useRef(new Set<string>());
64	  // Each grade's proof threshold, by grade, as typed; likewise each may be saved blank (none).
65	  const [gradeProof, setGradeProof] = useState<Record<string, string>>({});
66	  const proofGradeChosen = useRef(new Set<string>());
67	  const today = useSheetToday(sheet);
68	  const [policyDate, setPolicyDate] = useState('');
69	  // The policy date may be saved blank (back to the sheet's today), so entering its field marks it as the one to save.
70	  const policyChosen = useRef(false);
71	  const [numberingFrom, setNumberingFrom] = useState('');
72	  // Likewise the period numbering from may be saved blank (off).
73	  const numberingChosen = useRef(false);
74	  const [cap, setCap] = useState('');
75	  // Likewise the cap may be saved blank (none).
76	  const capChosen = useRef(false);
77	  const [proofThreshold, setProofThreshold] = useState('');
78	  // Likewise the proof threshold may be saved blank (none).
79	  const proofChosen = useRef(false);
80	  const [noteThreshold, setNoteThreshold] = useState('');
81	  // Likewise the note threshold may be saved blank (none).
82	  const noteChosen = useRef(false);
83	  // The grace days (not dated); likewise may be saved blank (off).
84	  const [graceDays, setGraceDays] = useState('');
85	  const graceChosen = useRef(false);
86	  // The entry date (not dated); likewise may be saved blank (off).
87	  const [entryDate, setEntryDate] = useState('');
88	  const entryChosen = useRef(false);
89	  // The pot (not dated); likewise may be saved blank (none).
90	  const [pot, setPot] = useState('');
91	  const potChosen = useRef(false);
92	  // The alert threshold (not dated); likewise may be saved blank (off).
93	  const [alertThreshold, setAlertThreshold] = useState('');
94	  const alertChosen = useRef(false);
95	  // The parent sheet (not dated); likewise may be saved blank (none).
96	  const [parent, setParent] = useState('');
97	  const parentChosen = useRef(false);
98	  // Entering the parent marks it as the one to save, as it is.
99	  const focusParent = () => {
100	    unchoosePolicy();
101	    parentChosen.current = true;
102	  };
103	  // Entering the alert threshold marks it as the one to save, as it is.
104	  const focusAlert = () => {
105	    unchoosePolicy();
106	    alertChosen.current = true;
107	  };
108	  // Entering the pot marks it as the one to save, as it is.
109	  const focusPot = () => {
110	    unchoosePolicy();
111	    potChosen.current = true;
112	  };
113	  // Entering the grace days marks them as the one to save, as they are.
114	  const focusGrace = () => {
115	    if (entryDate.trim() === '') entryChosen.current = false;
116	    unchoosePerms();
117	    if (policyDate.trim() === '') policyChosen.current = false;
118	    if (numberingFrom.trim() === '') numberingChosen.current = false;
119	    if (cap.trim() === '') capChosen.current = false;
120	    if (proofThreshold.trim() === '') proofChosen.current = false;
121	    if (noteThreshold.trim() === '') noteChosen.current = false;
122	    graceChosen.current = true;
123	  };
124	  // Entering the entry date marks it as the one to save, as it is.
125	  const focusEntry = () => {
126	    unchoosePerms();
127	    if (policyDate.trim() === '') policyChosen.current = false;
128	    if (numberingFrom.trim() === '') numberingChosen.current = false;
129	    if (cap.trim() === '') capChosen.current = false;
130	    if (proofThreshold.trim() === '') proofChosen.current = false;
131	    if (noteThreshold.trim() === '') noteChosen.current = false;
132	    if (graceDays.trim() === '') graceChosen.current = false;
133	    entryChosen.current = true;
134	  };
135	  // Each action's permission, by action, as typed; each may be saved blank (the standing rule).
136	  const [perms, setPerms] = useState<Record<string, string>>({});
137	  const permsChosen = useRef(new Set<string>());
138	  // Entering another field leaves a blank permission as it is.
139	  const unchoosePerms = (except?: string) => {
140	    for (const a of PERM_ACTIONS) {
141	      if (a !== except && (perms[a] ?? '').trim() === '') permsChosen.current.delete(a);
142	    }
143	    if (pot.trim() === '') potChosen.current = false;
144	    if (alertThreshold.trim() === '') alertChosen.current = false;
145	    if (parent.trim() === '') parentChosen.current = false;
146	    unchooseGradeGrace();
147	  };
148	  // Entering another field leaves a blank grade's grace days as they are.
149	  const unchooseGradeGrace = () => {
150	    for (const g of GRADES) {
151	      if ((gradeGrace[g] ?? '').trim() === '') graceGradeChosen.current.delete(g);
152	      if ((gradeProof[g] ?? '').trim() === '') proofGradeChosen.current.delete(g);
153	    }
154	  };
155	  // Entering a grade's grace days (or their from-date) marks them as one to save, as they are.
156	  const focusGradeGrace = (grade: string) => {
157	    unchoosePolicy();
158	    graceGradeChosen.current.add(grade);
159	  };
160	  // Entering a grade's proof threshold (or its from-date) marks it as one to save, as it is.
161	  const focusGradeProof = (grade: string) => {
162	    unchoosePolicy();
163	    proofGradeChosen.current.add(grade);
164	  };
165	  // Entering a permission marks it as one to save, as it is.
166	  const focusPerm = (action: string) => {
167	    if (policyDate.trim() === '') policyChosen.current = false;
168	    if (numberingFrom.trim() === '') numberingChosen.current = false;
169	    if (cap.trim() === '') capChosen.current = false;
170	    if (proofThreshold.trim() === '') proofChosen.current = false;
171	    if (noteThreshold.trim() === '') noteChosen.current = false;
172	    if (graceDays.trim() === '') graceChosen.current = false;
173	    if (entryDate.trim() === '') entryChosen.current = false;
174	    unchoosePerms(action);
175	    permsChosen.current.add(action);
176	  };
177	  // Entering another field leaves a blank policy date (and a blank period numbering from, and a blank cap) as it is.
178	  const unchoosePolicy = () => {
179	    unchoosePerms();
180	    if (policyDate.trim() === '') policyChosen.current = false;
181	    if (numberingFrom.trim() === '') numberingChosen.current = false;
182	    if (cap.trim() === '') capChosen.current = false;
183	    if (proofThreshold.trim() === '') proofChosen.current = false;
184	    if (noteThreshold.trim() === '') noteChosen.current = false;
185	    if (graceDays.trim() === '') graceChosen.current = false;
186	    if (entryDate.trim() === '') entryChosen.current = false;
187	  };
188	  // Each dated setting's from-date, by key, as typed.
189	  const [froms, setFroms] = useState<Record<string, string>>({});
190	  const fromField = (key: string, onFocus: () => void = unchoosePolicy) => (
191	    <input
192	      data-testid={`setting-${key}-from`}
193	      onFocus={onFocus}
194	      value={froms[key] ?? ''}
195	      placeholder="From YYYY-MM-DD (blank: the sheet's today)"
196	      onChange={(e) => {
197	        const value = e.target.value;
198	        setFroms((f) => ({ ...f, [key]: value }));
199	        saveSetting.reset();
200	      }}
201	    />
202	  );
203	  // Entering the cap (or its from-date) marks it as the one to save, as it is.
204	  const focusCap = () => {
205	    unchoosePerms();
206	    if (policyDate.trim() === '') policyChosen.current = false;
207	    if (numberingFrom.trim() === '') numberingChosen.current = false;
208	    if (proofThreshold.trim() === '') proofChosen.current = false;
209	    if (noteThreshold.trim() === '') noteChosen.current = false;
210	    if (graceDays.trim() === '') graceChosen.current = false;
211	    if (entryDate.trim() === '') entryChosen.current = false;
212	    capChosen.current = true;
213	  };
214	  // Entering the proof threshold (or its from-date) marks it as the one to save, as it is.
215	  const focusProof = () => {
216	    unchoosePerms();
217	    if (policyDate.trim() === '') policyChosen.current = false;
218	    if (numberingFrom.trim() === '') numberingChosen.current = false;
219	    if (cap.trim() === '') capChosen.current = false;
220	    if (graceDays.trim() === '') graceChosen.current = false;
221	    if (entryDate.trim() === '') entryChosen.current = false;
222	    if (noteThreshold.trim() === '') noteChosen.current = false;
223	    proofChosen.current = true;
224	  };
225	  // Entering the note threshold (or its from-date) marks it as the one to save, as it is.
226	  const focusNote = () => {
227	    unchoosePerms();
228	    if (policyDate.trim() === '') policyChosen.current = false;
229	    if (numberingFrom.trim() === '') numberingChosen.current = false;
230	    if (cap.trim() === '') capChosen.current = false;
231	    if (proofThreshold.trim() === '') proofChosen.current = false;
232	    if (graceDays.trim() === '') graceChosen.current = false;
233	    if (entryDate.trim() === '') entryChosen.current = false;
234	    noteChosen.current = true;
235	  };
236	  const [name, setName] = useState('');
237	  const [role, setRole] = useState('');
238	  const [delegateUser, setDelegateUser] = useState('');
239	  const [delegateFrom, setDelegateFrom] = useState('');
240	  const [delegateTo, setDelegateTo] = useState('');
241	  const saveSetting = useMutation({
242	    mutationFn: (body: { key: string; value: string; from?: string }) =>
243	      postJson<Settings>(`/api/sheets/${encodeURIComponent(sheet)}/settings`, { ...body, user }),
244	    onSuccess: (saved, body) => {
245	      setFroms((f) => ({ ...f, [body.key]: '' }));
246	      if (body.key === 'floor') setFloor('');
247	      else if (body.key === 'terms') setTerms('');
248	      else if (body.key.startsWith('terms-')) setGradeTerms((t) => ({ ...t, [body.key.slice('terms-'.length)]: '' }));
249	      else if (body.key === 'late-pct') setLatePct('');
250	      else if (body.key === 'fiscal-start-month') setFiscalStart('');
251	      else if (body.key === 'policy-date') {
252	        setPolicyDate('');
253	        policyChosen.current = false;
254	      }
255	      else if (body.key === 'period-numbering-from') {
256	        setNumberingFrom('');
257	        numberingChosen.current = false;
258	      }
259	      else if (body.key === 'cap') {
260	        setCap('');
261	        capChosen.current = false;
262	      }
263	      else if (body.key.startsWith('perm-')) {
264	        const action = body.key.slice('perm-'.length);
265	        setPerms((p) => ({ ...p, [action]: '' }));
266	        permsChosen.current.delete(action);
267	      }
268	      else if (body.key.startsWith('grace-') && body.key !== 'grace-days') {
269	        const grade = body.key.slice('grace-'.length);
270	        setGradeGrace((t) => ({ ...t, [grade]: '' }));
271	        graceGradeChosen.current.delete(grade);
272	      }
273	      else if (body.key === 'grace-days') {
274	        setGraceDays('');
275	        graceChosen.current = false;
276	      }
277	      else if (body.key === 'pot') {
278	        setPot('');
279	        potChosen.current = false;
280	        queryClient.invalidateQueries({ queryKey: poolsKey(sheet) });
281	      }
282	      else if (body.key === 'alert-threshold') {
283	        setAlertThreshold('');
284	        alertChosen.current = false;
285	      }
286	      else if (body.key === 'parent') {
287	        setParent('');
288	        parentChosen.current = false;
289	        queryClient.invalidateQueries({ queryKey: ['sheet', sheet, 'inherited-rates'] });
290	      }
291	      else if (body.key === 'entry-date') {
292	        setEntryDate('');
293	        entryChosen.current = false;
294	      }
295	      else if (body.key.startsWith('proof-threshold-')) {
296	        const grade = body.key.slice('proof-threshold-'.length);
297	        setGradeProof((t) => ({ ...t, [grade]: '' }));
298	        proofGradeChosen.current.delete(grade);
299	      }
300	      else if (body.key === 'proof-threshold') {
301	        setProofThreshold('');
302	        proofChosen.current = false;
303	      }
304	      else if (body.key === 'note-threshold') {
305	        setNoteThreshold('');
306	        noteChosen.current = false;
307	      }
308	      else setLimit('');
309	      queryClient.setQueryData(settingsKey(sheet), saved);
310	    },
311	  });
312	  const saveRole = useMutation({
313	    mutationFn: (body: { name: string; role: string }) =>
314	      postJson<Settings>(`/api/sheets/${encodeURIComponent(sheet)}/roles`, { ...body, user }),
315	    onSuccess: (saved) => {
316	      setName('');
317	      setRole('');
318	      queryClient.setQueryData(settingsKey(sheet), saved);
319	    },
320	  });
321	  const saveDelegate = useMutation({
322	    mutationFn: (body: { name: string; from: string; to: string }) =>
323	      postJson<Settings>(`/api/sheets/${encodeURIComponent(sheet)}/delegations`, { ...body, user }),
324	    onSuccess: (saved) => {
325	      setDelegateUser('');
326	      setDelegateFrom('');
327	      setDelegateTo('');
328	      queryClient.setQueryData(settingsKey(sheet), saved);
329	    },
330	  });
331	  return (
332	    <>
333	      <form
334	        data-testid="settings-form"
335	        onSubmit={(e) => {
336	          e.preventDefault();
337	          submitSetting(() => {
338	            saveSetting.reset();
339	            // A dated setting is saved from its from-date (blank: the sheet's today).
340	            const save = (body: { key: string; value: string }) =>
341	              saveSetting.mutateAsync({ ...body, from: (froms[body.key] ?? '').trim() });
342	            const policy = policyDate.trim() !== '' || policyChosen.current;
343	            const numbering = numberingFrom.trim() !== '' || numberingChosen.current;
344	            const capped = cap.trim() !== '' || capChosen.current;
345	            const proofed = proofThreshold.trim() !== '' || proofChosen.current;
346	            const noted = noteThreshold.trim() !== '' || noteChosen.current;
347	            const graced = graceDays.trim() !== '' || graceChosen.current;
348	            const entered = entryDate.trim() !== '' || entryChosen.current;
349	            const potted = pot.trim() !== '' || potChosen.current;
350	            const alerted = alertThreshold.trim() !== '' || alertChosen.current;
351	            const parented = parent.trim() !== '' || parentChosen.current;
352	            const ownTerms = GRADES.filter((g) => (gradeTerms[g] ?? '').trim() !== '');
353	            const ownGrace = GRADES.filter((g) => (gradeGrace[g] ?? '').trim() !== '' || graceGradeChosen.current.has(g));
354	            const ownProof = GRADES.filter((g) => (gradeProof[g] ?? '').trim() !== '' || proofGradeChosen.current.has(g));
355	            const permitted = PERM_ACTIONS.filter((a) => (perms[a] ?? '').trim() !== '' || permsChosen.current.has(a));
356	            if (terms.trim() !== '' || ownTerms.length > 0 || ownGrace.length > 0 || latePct.trim() !== '' || fiscalStart.trim() !== '' || policy || numbering || capped || proofed || ownProof.length > 0
357	                || noted || graced || entered || potted || alerted || parented || permitted.length > 0) {
358	              const saves = [
359	                ...(limit.trim() !== '' ? [{ key: 'clerk-limit', value: limit.trim() }] : []),
360	                ...(floor.trim() !== '' ? [{ key: 'floor', value: floor.trim() }] : []),
361	                ...(terms.trim() !== '' ? [{ key: 'terms', value: terms.trim() }] : []),
362	                ...ownTerms.map((g) => ({ key: `terms-${g}`, value: gradeTerms[g].trim() })),
363	                ...(latePct.trim() !== '' ? [{ key: 'late-pct', value: latePct.trim() }] : []),
364	                ...(fiscalStart.trim() !== '' ? [{ key: 'fiscal-start-month', value: fiscalStart.trim() }] : []),
365	                ...ownGrace.map((g) => ({ key: `grace-${g}`, value: (gradeGrace[g] ?? '').trim() })),
366	                ...(policy ? [{ key: 'policy-date', value: policyDate.trim() }] : []),
367	                ...(numbering ? [{ key: 'period-numbering-from', value: numberingFrom.trim() }] : []),
368	                ...(capped ? [{ key: 'cap', value: cap.trim() }] : []),
369	                ...(proofed ? [{ key: 'proof-threshold', value: proofThreshold.trim() }] : []),
370	                ...ownProof.map((g) => ({ key: `proof-threshold-${g}`, value: (gradeProof[g] ?? '').trim() })),
371	                ...(noted ? [{ key: 'note-threshold', value: noteThreshold.trim() }] : []),
372	                ...(graced ? [{ key: 'grace-days', value: graceDays.trim() }] : []),
373	                ...(entered ? [{ key: 'entry-date', value: entryDate.trim() }] : []),
374	                ...(potted ? [{ key: 'pot', value: pot.trim() }] : []),
375	                ...(alerted ? [{ key: 'alert-threshold', value: alertThreshold.trim() }] : []),
376	                ...(parented ? [{ key: 'parent', value: parent.trim() }] : []),
377	                ...permitted.map((a) => ({ key: `perm-${a}`, value: (perms[a] ?? '').trim() })),
378	              ];
379	              return saves.reduce<Promise<unknown>>((done, body) => done.then(() => save(body)), Promise.resolve());
380	            }
381	            if (floor.trim() === '') return save({ key: 'clerk-limit', value: limit.trim() });
382	            const saveFloor = () => save({ key: 'floor', value: floor.trim() });
383	            return limit.trim() === ''
384	              ? saveFloor()
385	              : save({ key: 'clerk-limit', value: limit.trim() }).then(saveFloor);
386	          });
387	        }}
388	      >
389	        Clerk limit: <span data-testid="setting-clerk-limit-current">{settings?.clerkLimit ?? ''}</span>{' '}
390	        <input
391	          data-testid="setting-clerk-limit"
392	          onFocus={unchoosePolicy}
393	          value={limit}
394	          placeholder="Clerk limit (blank: none)"
395	          onChange={(e) => {
396	            setLimit(e.target.value);
397	            saveSetting.reset();
398	          }}
399	        />{' '}
400	        {fromField('clerk-limit')}{' '}
401	        Floor: <span data-testid="setting-floor-current">{settings?.floor ?? ''}</span>{' '}
402	        <input
403	          data-testid="setting-floor"
404	          onFocus={unchoosePolicy}
405	          value={floor}
406	          placeholder="Floor (blank: unchanged)"
407	          onChange={(e) => {
408	            setFloor(e.target.value);
409	            saveSetting.reset();
410	          }}
411	        />{' '}
412	        {fromField('floor')}{' '}
413	        Terms (days): <span data-testid="setting-terms-current">{settings?.terms ?? ''}</span>{' '}
414	        <input
415	          data-testid="setting-terms"
416	          onFocus={unchoosePolicy}
417	          value={terms}
418	          placeholder="Terms in days (blank: unchanged)"
419	          onChange={(e) => {
420	            setTerms(e.target.value);
421	            saveSetting.reset();
422	          }}
423	        />{' '}
424	        {fromField('terms')}{' '}
425	        {GRADES.map((g) => (
426	          <span key={g}>
427	            Terms for grade {g} (days): <span data-testid={`setting-terms-${g}-current`}>{settings?.gradeTerms?.[g] ?? ''}</span>{' '}
428	            <input
429	              data-testid={`setting-terms-${g}`}
430	              onFocus={unchoosePolicy}
431	              value={gradeTerms[g] ?? ''}
432	              placeholder={`Grade ${g} terms in days (blank: unchanged)`}
433	              onChange={(e) => {
434	                const value = e.target.value;
435	                setGradeTerms((t) => ({ ...t, [g]: value }));
436	                saveSetting.reset();
437	              }}
438	            />{' '}
439	            {fromField(`terms-${g}`)}{' '}

